-- 496_nightly_look_candidates_round3.sql — round-3 candidates for the nightly looks catalog (Kevin 2026-09-11: "we'll
-- miss the cartoony / comic looks … watercolor-adjacent looks that might render more reliably … our old mediums
-- are too sharp around the edges … test all of them"). Hypothesis from round 1 (NIGHTLY_LOOK_TALLY.md): HARD EDGES
-- (ink outlines, halftone, crisp strokes, flat cel fills) are what makes a swapped face read pasted-on; a comic or
-- watercolor look survives the swap when faces are painted with continuous soft-edged skin. Every cast fragment
-- LEADS with the swap-safety clause (natural eye size — the June cartoon-eye lesson) ahead of the style words.
-- Inert rows (nightly_look=true, nightly_surfaces={} = ungraded/parked): reached only by force_look until graded.
INSERT INTO public.dream_mediums
  (key, label, description, directive, flux_fragment, face_swap_flux_fragment, sort_order, allowed_models, preferred_model, client_meta,
   is_active, is_public, is_dream_eligible, is_scene_eligible, is_scene_only, is_character_only, is_bot_only, nightly_skip, face_swaps, character_render_mode,
   nightly_look, nightly_surfaces, weight)
SELECT v.key, v.label, v.description, v.directive, v.flux_fragment, v.face_swap_flux_fragment, v.sort_order, v.allowed_models, v.preferred_model, v.client_meta,
       true, false, false, false, false, false, false, true, true, 'natural',
       true, '{}'::text[], 1
FROM (VALUES
  ('nightly_painted_comic_cover', 'Painted Comic Cover', 'Fully painted comic-book cover, soft edges', 'Render the entire scene as painted comic cover: fully painted comic-book cover art, dramatic saturated color, heroic layered composition, smooth brush-modelled skin and fabric, painted highlights and shadow, soft painted edges throughout, glossy printed-cover finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'fully painted comic-book cover art, dramatic saturated color, heroic layered composition, smooth brush-modelled skin and fabric, painted highlights and shadow, soft painted edges throughout, glossy printed-cover finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, fully painted comic-book cover art, dramatic saturated color, heroic layered composition, smooth brush-modelled skin and fabric, painted highlights and shadow, soft painted edges throughout, glossy printed-cover finish', 980, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_soft_comic', 'Soft-Shaded Comic', 'Digital comic with airbrushed shading', 'Render the entire scene as soft-shaded comic: digital comic art with soft airbrushed shading, realistic adult proportions, smooth blended skin tones, gentle painted edges, soft cel gradients, saturated comic palette, clean digital finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'digital comic art with soft airbrushed shading, realistic adult proportions, smooth blended skin tones, gentle painted edges, soft cel gradients, saturated comic palette, clean digital finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, digital comic art with soft airbrushed shading, realistic adult proportions, smooth blended skin tones, gentle painted edges, soft cel gradients, saturated comic palette, clean digital finish', 981, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_rotoscope', 'Rotoscoped Animation', 'Hand-traced live-action animation', 'Render the entire scene as rotoscoped animation: rotoscoped animation frame hand-traced over live-action footage, realistic human proportions and natural gestures, flat painted color regions with softly wavering edges, simplified painted backgrounds, animated-film finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'rotoscoped animation frame hand-traced over live-action footage, realistic human proportions and natural gestures, flat painted color regions with softly wavering edges, simplified painted backgrounds, animated-film finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, rotoscoped animation frame hand-traced over live-action footage, realistic human proportions and natural gestures, flat painted color regions with softly wavering edges, simplified painted backgrounds, animated-film finish', 982, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_painted_animation', 'Painted Animation Frame', 'Every frame hand-painted in oil', 'Render the entire scene as painted animation frame: hand-painted oil animation frame, every frame painted in oil with visible brushstrokes, realistic proportions, painterly movement in the strokes, filmic composition, painted-film finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'hand-painted oil animation frame, every frame painted in oil with visible brushstrokes, realistic proportions, painterly movement in the strokes, filmic composition, painted-film finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, hand-painted oil animation frame, every frame painted in oil with visible brushstrokes, realistic proportions, painterly movement in the strokes, filmic composition, painted-film finish', 983, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_airbrush_poster', 'Retro Airbrush Poster', 'Smooth 80s airbrush illustration', 'Render the entire scene as retro airbrush poster: retro airbrush poster illustration, smooth airbrushed gradients, glossy highlights, bold saturated poster color, softly blended skin, polished 1980s illustration finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'retro airbrush poster illustration, smooth airbrushed gradients, glossy highlights, bold saturated poster color, softly blended skin, polished 1980s illustration finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, retro airbrush poster illustration, smooth airbrushed gradients, glossy highlights, bold saturated poster color, softly blended skin, polished 1980s illustration finish', 984, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_marker', 'Marker Illustration', 'Alcohol-marker sketchbook rendering', 'Render the entire scene as marker illustration: alcohol-marker illustration, blended marker skin tones, soft layered translucent color, faint graphite under-drawing, marker streak texture in the surroundings, sketchbook finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'alcohol-marker illustration, blended marker skin tones, soft layered translucent color, faint graphite under-drawing, marker streak texture in the surroundings, sketchbook finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, alcohol-marker illustration, blended marker skin tones, soft layered translucent color, faint graphite under-drawing, marker streak texture in the surroundings, sketchbook finish', 985, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_ink_wash_comic', 'Ink-Wash Comic', 'Brush-inked comic with watercolor wash', 'Render the entire scene as ink-wash comic: brush-inked comic with watercolor wash, loose broken brush ink, transparent color washes, softly painted skin, expressive comic composition, hand-made finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'brush-inked comic with watercolor wash, loose broken brush ink, transparent color washes, softly painted skin, expressive comic composition, hand-made finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, brush-inked comic with watercolor wash, loose broken brush ink, transparent color washes, softly painted skin, expressive comic composition, hand-made finish', 986, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_soft_pop_art', 'Soft Pop Art', 'Pop art with airbrushed smooth faces', 'Render the entire scene as soft pop art: pop-art illustration with airbrushed smooth faces, bold flat color blocks in the surroundings, halftone dot texture confined to backdrop shapes, saturated retro palette, softly blended skin, silkscreen-poster finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'pop-art illustration with airbrushed smooth faces, bold flat color blocks in the surroundings, halftone dot texture confined to backdrop shapes, saturated retro palette, softly blended skin, silkscreen-poster finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, pop-art illustration with airbrushed smooth faces, bold flat color blocks in the surroundings, halftone dot texture confined to backdrop shapes, saturated retro palette, softly blended skin, silkscreen-poster finish', 987, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_painted_graphic_novel', 'Painted Graphic Novel', 'Fully painted gouache-and-acrylic panels', 'Render the entire scene as painted graphic novel: fully painted graphic-novel art, gouache and acrylic panel painting, moody saturated color, brush-modelled realistic faces, painted textures throughout, printed graphic-novel finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'fully painted graphic-novel art, gouache and acrylic panel painting, moody saturated color, brush-modelled realistic faces, painted textures throughout, printed graphic-novel finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, fully painted graphic-novel art, gouache and acrylic panel painting, moody saturated color, brush-modelled realistic faces, painted textures throughout, printed graphic-novel finish', 988, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_lineless_watercolor', 'Lineless Watercolor', 'Loose wet-on-wet watercolor, no lines', 'Render the entire scene as lineless watercolor: loose lineless watercolor painting, wet-on-wet washes with soft blooming edges, faces built from graded transparent washes, granulating pigment on cold-press paper, luminous paper-white highlights. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'loose lineless watercolor painting, wet-on-wet washes with soft blooming edges, faces built from graded transparent washes, granulating pigment on cold-press paper, luminous paper-white highlights', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, loose lineless watercolor painting, wet-on-wet washes with soft blooming edges, faces built from graded transparent washes, granulating pigment on cold-press paper, luminous paper-white highlights', 989, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_watercolor_portrait', 'Watercolor Portrait', 'Watercolor with fully modelled skin', 'Render the entire scene as watercolor portrait: watercolor portrait painting with fully modelled skin, careful graded skin washes, opaque gouache highlights, soft edges, loose splashy paper texture kept to the surroundings. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'watercolor portrait painting with fully modelled skin, careful graded skin washes, opaque gouache highlights, soft edges, loose splashy paper texture kept to the surroundings', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, watercolor portrait painting with fully modelled skin, careful graded skin washes, opaque gouache highlights, soft edges, loose splashy paper texture kept to the surroundings', 990, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_digital_watercolor', 'Digital Watercolor', 'Smooth digital watercolor', 'Render the entire scene as digital watercolor: smooth digital watercolor illustration, soft controlled bleeds, gentle edge softness, layered translucent color, clean luminous finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'smooth digital watercolor illustration, soft controlled bleeds, gentle edge softness, layered translucent color, clean luminous finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, smooth digital watercolor illustration, soft controlled bleeds, gentle edge softness, layered translucent color, clean luminous finish', 991, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_gouache_portrait', 'Gouache Portrait', 'Opaque gouache, soft matte skin', 'Render the entire scene as gouache portrait: opaque gouache portrait painting, soft blended matte skin, saturated poster color, visible brush dabs in the surroundings, chalky matte finish, hand-painted plate. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'opaque gouache portrait painting, soft blended matte skin, saturated poster color, visible brush dabs in the surroundings, chalky matte finish, hand-painted plate', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, opaque gouache portrait painting, soft blended matte skin, saturated poster color, visible brush dabs in the surroundings, chalky matte finish, hand-painted plate', 992, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_aquarelle_graphite', 'Aquarelle over Graphite', 'Watercolor over a faint pencil drawing', 'Render the entire scene as aquarelle over graphite: transparent aquarelle over a faint graphite drawing, soft luminous washes, delicate pencil under-drawing showing through, gently blended skin, airy paper-white highlights. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'transparent aquarelle over a faint graphite drawing, soft luminous washes, delicate pencil under-drawing showing through, gently blended skin, airy paper-white highlights', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, transparent aquarelle over a faint graphite drawing, soft luminous washes, delicate pencil under-drawing showing through, gently blended skin, airy paper-white highlights', 993, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_soft_brush_illustration', 'Soft Brush Illustration', 'Brush-painted editorial illustration', 'Render the entire scene as soft brush illustration: brush-painted editorial illustration, soft painted edges, rich saturated color, confident brush modelling, hand-painted magazine-illustration finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'brush-painted editorial illustration, soft painted edges, rich saturated color, confident brush modelling, hand-painted magazine-illustration finish', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, brush-painted editorial illustration, soft painted edges, rich saturated color, confident brush modelling, hand-painted magazine-illustration finish', 994, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_pastel_portrait', 'Pastel Portrait', 'Pastel with fully modelled skin', 'Render the entire scene as pastel portrait: soft pastel portrait painting, fully modelled velvety skin, blended pastel strokes, toned paper texture in the surroundings, luminous layered color. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces and natural eye size.', 'soft pastel portrait painting, fully modelled velvety skin, blended pastel strokes, toned paper texture in the surroundings, luminous layered color', 'lifelike adult faces with realistic human facial proportions and true-to-life eyes at natural size and spacing, soft pastel portrait painting, fully modelled velvety skin, blended pastel strokes, toned paper texture in the surroundings, luminous layered color', 995, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"round":3,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb)
